res=set()
def pairings(rem):
    if not rem: yield []; return
    a=rem[0]
    for b in rem[1:]:
        r=[x for x in rem if x not in (a,b)]
        for p in pairings(r): yield [(a,b)]+p
for p in pairings(faces):
    if all(b not in adj[a] for a,b in p):
        for a,b in p:
            if a=="Hand": res.add(b)
            if b=="Hand": res.add(a)
